//
// NOVEL (hand-authored) — not generated by CLI Printing Press.
//
// N131.5.5 F-5: `activities breakdown --help` printed
// "garmin-pp-cli activities breakdown --aggregation lifetime --metric duration",
// which exits 2 with `required flag "start-date" not set`. SKILL.md and
// README.md only name the command, so an agent that wants its arguments reads
// --help and copies the one example there. An example that cannot run is worse
// than no example.
//
// The check is offline on purpose: it parses the printed example against the
// command's own flag set, so it fails on a stale example without spending a
// request against Garmin.

package cli

import (
	"strings"
	"testing"

	"github.com/spf13/cobra"
)

// exampleArgs strips the binary name and command path from a Cobra Example
// line and returns the arguments that follow.
func exampleArgs(t *testing.T, example string, path ...string) []string {
	t.Helper()
	fields := strings.Fields(strings.TrimSpace(example))
	if len(fields) < 1+len(path) {
		t.Fatalf("example %q is shorter than the command path %v", example, path)
	}
	if fields[0] != "garmin-pp-cli" {
		t.Fatalf("example %q does not start with the binary name", example)
	}
	for i, part := range path {
		if fields[1+i] != part {
			t.Fatalf("example %q does not name the command %v", example, path)
		}
	}
	return fields[1+len(path):]
}

func TestActivitiesBreakdownExampleSetsEveryRequiredFlag(t *testing.T) {
	root := RootCmd()
	cmd, _, err := root.Find([]string{"activities", "breakdown"})
	if err != nil {
		t.Fatalf("finding activities breakdown: %v", err)
	}
	if cmd.Example == "" {
		t.Fatal("activities breakdown prints no example")
	}

	args := exampleArgs(t, cmd.Example, "activities", "breakdown")
	parsed := &cobra.Command{Use: cmd.Use}
	parsed.Flags().AddFlagSet(cmd.Flags())
	if err := parsed.ParseFlags(args); err != nil {
		t.Fatalf("the printed example does not parse against the command's own flags: %v", err)
	}

	// The two flags the command's RunE refuses to run without
	// (activities_breakdown.go: `required flag "start-date" not set`, then the
	// same for end-date). --metric and --aggregation carry defaults.
	for _, required := range []string{"start-date", "end-date"} {
		if !parsed.Flags().Changed(required) {
			t.Errorf("the printed example omits --%s, which the command requires: %q", required, strings.TrimSpace(cmd.Example))
		}
	}
	// --aggregation is hidden and defaulted; naming it in the example teaches a
	// flag the help text does not list.
	if parsed.Flags().Changed("aggregation") {
		t.Errorf("the printed example names the hidden --aggregation flag: %q", strings.TrimSpace(cmd.Example))
	}
}
